"s = torch.ones(2, 3, requires_grad=True) * 2\ns.detach_()\ns.requires_grad, s.grad_fn",
"num_hiddens = 32\nnet = d2l.RNNModelScratch(len(vocab), num_hiddens, d2l.try_gpu(), get_params, init_rnn_state, rnn)\nloss = nn.CrossEntropyLoss()\nupdater = lambda batch_size: d2l.sgd(net.params, 1, batch_size)\nppl, speed = d2l.train_epoch_ch8(net, train_iter, loss, updater, d2l.try_gpu(), False)\n20 < ppl < 30, speed > 0",
"num_hiddens = 256\nrnn_layer = nn.RNN(len(vocab), num_hiddens)\nrnn_layer, [(n, tuple(p.shape)) for n, p in rnn_layer.named_parameters()], rnn_layer.hidden_size, rnn_layer.num_layers, rnn_layer.bidirectional",
"state = torch.zeros((1, batch_size, num_hiddens))\nstate.shape",
