"out2, h2 = lay(x)\nbool((out2 == out).all())",
"device = d2l.try_gpu()\nnet = d2l.RNNModel(rnn_layer, vocab_size=len(vocab))\nnet = net.to(device)\nlen(d2l.predict_ch8('time traveller', 10, net, vocab, device)), net",
